-- Limpia mensajes de chat que quedaron de tickets de prueba ya borrados (los folios se reutilizan) y repone los de la demostracion.
START TRANSACTION;
DELETE FROM mensajes_chat WHERE folio+0 BETWEEN 11112602 AND 11112620;
DELETE FROM mensajes_chat WHERE folio NOT IN (SELECT folio FROM (SELECT folio FROM tickets) AS t);
INSERT INTO mensajes_chat (folio, remitente, texto, hora) VALUES ('11112602', 'Sistema', 'Gracias por crear tu centinela con el folio #11112602. Un tecnico ya atendio esta falla (Folio origen: #09112606). Solucion aplicada: Se reviso el mouse en sitio: el sensor optico estaba danado. Se reemplazo por uno nuevo del stock y se valido el funcionamiento con el asesor. Ya se valido con esa solucion. Te agradecemos que lo sigas reportando para que tu campana llegue al 100% y se hagan los cambios solicitados.', '09:20');
INSERT INTO mensajes_chat (folio, remitente, texto, hora) VALUES ('11112603', 'Sistema', 'Gracias por crear tu centinela con el folio #11112603. Un tecnico ya atendio esta falla (Folio origen: #09112606). Solucion aplicada: Se reviso el mouse en sitio: el sensor optico estaba danado. Se reemplazo por uno nuevo del stock y se valido el funcionamiento con el asesor. Ya se valido con esa solucion. Te agradecemos que lo sigas reportando para que tu campana llegue al 100% y se hagan los cambios solicitados.', '10:10');
INSERT INTO mensajes_chat (folio, remitente, texto, hora) VALUES ('11112604', 'Sistema', 'Gracias por crear tu centinela con el folio #11112604. Un tecnico ya atendio esta falla (Folio origen: #09112606). Solucion aplicada: Se reviso el mouse en sitio: el sensor optico estaba danado. Se reemplazo por uno nuevo del stock y se valido el funcionamiento con el asesor. Ya se valido con esa solucion. Te agradecemos que lo sigas reportando para que tu campana llegue al 100% y se hagan los cambios solicitados.', '11:40');
COMMIT;
SELECT folio, COUNT(*) AS mensajes FROM mensajes_chat WHERE folio+0 >= 9112604 GROUP BY folio ORDER BY folio;
